return [{ json: { status: 'Config loaded', testnet: cfg.BYBIT_TESTNET } }];

// =============================================
// STEP 1: Get top trading pairs by 24h volume
// =============================================
const cfg = $getWorkflowStaticData('global');
const crypto = require('crypto');

// Check if bot is stopped
const store = $getWorkflowStaticData('global');
if (store.botStopped) {
  return []; // Bot is stopped, skip scanning
}

const isTestnet = (cfg.BYBIT_TESTNET || 'true').toLowerCase() === 'true';
const baseUrl = isTestnet ? 'https://api-testnet.bybit.com' : 'https://api.bybit.com';
const MIN_VOLUME = parseFloat(cfg.MIN_VOLUME_24H || '50000000');

// Fetch spot tickers
const spotResponse = await this.helpers.httpRequest({
  method: 'GET',
  url: `${baseUrl}/v5/market/tickers?category=spot`
});

if (spotResponse.retCode !== 0) {
  throw new Error(`Bybit API error: ${spotResponse.retMsg}`);
}

// Filter USDT pairs with volume > $50M, sort by volume
const pairs = spotResponse.result.list
  .filter(t => t.symbol.endsWith('USDT'))
  .map(t => ({
    symbol: t.symbol,
    lastPrice: parseFloat(t.lastPrice),
    volume24h: parseFloat(t.turnover24h),
    change24h: parseFloat(t.price24hPcnt) * 100
  }))
  .filter(t => t.volume24h >= MIN_VOLUME)
  .sort((a, b) => b.volume24h - a.volume24h)
  .slice(0, 20); // Top 20 pairs

return pairs.map(p => ({ json: { ...p, baseUrl } }));

// =============================================
// STEP 2: Fetch candles for 3 timeframes
// =============================================
const cfg = $getWorkflowStaticData('global');
const pair = $input.first().json;
const baseUrl = pair.baseUrl;
const symbol = pair.symbol;

async function fetchKlines(interval, limit) {
  for (let attempt = 1; attempt <= 3; attempt++) {
    try {
      const resp = await this.helpers.httpRequest({
        method: 'GET',
        url: `${baseUrl}/v5/market/kline?category=spot&symbol=${symbol}&interval=${interval}&limit=${limit}`
      });
      if (resp.retCode === 0) return resp.result.list;
      if (resp.retCode === 10006) {
        await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 1000));
        continue;
      }
      return [];
    } catch(e) {
      if (attempt === 3) return [];
      await new Promise(r => setTimeout(r, Math.pow(2, attempt) * 1000));
    }
  }
  return [];
}

// Fetch 3 timeframes: 4H (senior), 1H (medium), 15m (junior)
const [candles4H, candles1H, candles15m] = await Promise.all([
  fetchKlines.call(this, '240', '100'),  // 4H, 100 candles
  fetchKlines.call(this, '60', '100'),   // 1H, 100 candles
  fetchKlines.call(this, '15', '50')     // 15m, 50 candles
]);

// Format candles: [startTime, open, high, low, close, volume, turnover]
function formatCandles(raw) {
  return raw.map(c => ({
    time: parseInt(c[0]),
    open: parseFloat(c[1]),
    high: parseFloat(c[2]),
    low: parseFloat(c[3]),
    close: parseFloat(c[4]),
    volume: parseFloat(c[5])
  })).reverse(); // oldest first
}

return [{
  json: {
    symbol: pair.symbol,
    lastPrice: pair.lastPrice,
    volume24h: pair.volume24h,
    change24h: pair.change24h,
    candles_4h: formatCandles(candles4H),
    candles_1h: formatCandles(candles1H),
    candles_15m: formatCandles(candles15m),
    baseUrl
  }
}];

// =============================================
// STEP 3: Pre-process data for Claude analysis
// Compute support/resistance levels, patterns
// =============================================
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;

function findLevels(candles, tolerance = 0.002) {
  if (!candles || candles.length === 0) return [];

  const levels = [];
  const highs = candles.map(c => c.high);
  const lows = candles.map(c => c.low);

  // Find swing highs and lows
  for (let i = 2; i < candles.length - 2; i++) {
    // Swing high
    if (highs[i] > highs[i-1] && highs[i] > highs[i-2] && 
        highs[i] > highs[i+1] && highs[i] > highs[i+2]) {
      levels.push({ price: highs[i], type: 'resistance' });
    }
    // Swing low
    if (lows[i] < lows[i-1] && lows[i] < lows[i-2] && 
        lows[i] < lows[i+1] && lows[i] < lows[i+2]) {
      levels.push({ price: lows[i], type: 'support' });
    }
  }

  // Cluster nearby levels and count touches
  const clustered = [];
  for (const level of levels) {
    const existing = clustered.find(l => 
      Math.abs(l.price - level.price) / level.price < tolerance
    );
    if (existing) {
      existing.touches++;
      existing.price = (existing.price + level.price) / 2;
    } else {
      clustered.push({ ...level, touches: 1 });
    }
  }

  // Count additional touches from all candles
  for (const level of clustered) {
    for (const candle of candles) {
      if (Math.abs(candle.high - level.price) / level.price < tolerance ||
          Math.abs(candle.low - level.price) / level.price < tolerance) {
        level.touches++;
      }
    }
  }

  return clustered.sort((a, b) => b.touches - a.touches).slice(0, 10);
}

function detectTrend(candles) {
  if (!candles || candles.length < 20) return 'sideways';
  const recent = candles.slice(-20);
  const sma20 = recent.reduce((s, c) => s + c.close, 0) / 20;
  const first5 = recent.slice(0, 5).reduce((s, c) => s + c.close, 0) / 5;
  const last5 = recent.slice(-5).reduce((s, c) => s + c.close, 0) / 5;

  if (last5 > sma20 * 1.01 && last5 > first5) return 'up';
  if (last5 < sma20 * 0.99 && last5 < first5) return 'down';
  return 'sideways';
}

function detectConsolidation(candles) {
  if (!candles || candles.length < 10) return false;
  const recent = candles.slice(-10);
  const highs = recent.map(c => c.high);
  const lows = recent.map(c => c.low);
  const range = Math.max(...highs) - Math.min(...lows);
  const avgPrice = recent.reduce((s, c) => s + c.close, 0) / recent.length;
  return (range / avgPrice) < 0.02; // < 2% range = consolidation
}

function getAvgVolume(candles) {
  if (!candles || candles.length === 0) return 0;
  return candles.reduce((s, c) => s + c.volume, 0) / candles.length;
}

// Summarize last N candles for Claude (reduce token usage)
function summarizeCandles(candles, count = 20) {
  if (!candles) return [];
  return candles.slice(-count).map(c => ({
    t: c.time, o: c.open, h: c.high, l: c.low, c: c.close, v: Math.round(c.volume)
  }));
}

const analysis = {
  symbol: data.symbol,
  lastPrice: data.lastPrice,
  volume24h: data.volume24h,
  change24h: data.change24h,

  trend_4h: detectTrend(data.candles_4h),
  trend_1h: detectTrend(data.candles_1h),

  levels_4h: findLevels(data.candles_4h),
  levels_1h: findLevels(data.candles_1h),

  consolidation_15m: detectConsolidation(data.candles_15m),
  avgVolume_1h: getAvgVolume(data.candles_1h),

  candles_4h_recent: summarizeCandles(data.candles_4h, 30),
  candles_1h_recent: summarizeCandles(data.candles_1h, 30),
  candles_15m_recent: summarizeCandles(data.candles_15m, 30),

  baseUrl: data.baseUrl
};

return [{ json: analysis }];

// =============================================
// STEP 4: Call Claude API for market analysis
// =============================================
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;

const SYSTEM_PROMPT = `Ты — профессиональный трейдер, торгующий по системе Александра Герчика.
Ты анализируешь криптовалютные графики на Bybit.

ПРАВИЛА АНАЛИЗА:
1) Определи тренд на старшем таймфрейме (4H/1D).
2) Найди ключевые уровни поддержки/сопротивления.
3) Оцени силу уровня (касания, объём, ложные пробои).
4) Ищи точку входа ТОЛЬКО от уровня с подтверждением.
5) НЕ входи против тренда старшего ТФ.
6) НЕ входи без чёткого стоп-лосса за уровнем.
7) Зона консолидации перед входом обязательна.
8) Приоритет уровням с ложным пробоем.

ФОРМАТ ОТВЕТА строго JSON:
{
  "action": "BUY|SELL|WAIT",
  "confidence": 0-100,
  "pair": "SYMBOL",
  "market_type": "spot|futures",
  "entry_price": number,
  "stop_loss": number,
  "take_profit_1": number,
  "take_profit_2": number,
  "take_profit_3": number,
  "risk_reward_ratio": number,
  "reasoning": "краткое объяснение на русском",
  "level_strength": "strong|medium|weak",
  "trend_direction": "up|down|sideways",
  "timeframe_alignment": true|false
}

КРИТЕРИИ ДЛЯ ВХОДА (ВСЕ должны быть true):
- confidence >= 75
- risk_reward_ratio >= 3
- timeframe_alignment == true
- level_strength == "strong" или "medium"

Если ХОТЬ ОДИН критерий не выполнен — action = "WAIT".

ВАЖНО: Отвечай ТОЛЬКО валидным JSON. Никакого текста до или после JSON.`;

const userMessage = `Проанализируй пару ${data.symbol}.

Текущая цена: ${data.lastPrice}
Объём 24ч: $${(data.volume24h / 1e6).toFixed(1)}M
Изменение 24ч: ${data.change24h.toFixed(2)}%

Тренд 4H: ${data.trend_4h}
Тренд 1H: ${data.trend_1h}
Консолидация 15m: ${data.consolidation_15m ? 'ДА' : 'НЕТ'}

Уровни 4H (цена, тип, касания):
${data.levels_4h.map(l => `  ${l.price.toFixed(2)} - ${l.type} - ${l.touches} касаний`).join('\n')}

Уровни 1H:
${data.levels_1h.map(l => `  ${l.price.toFixed(2)} - ${l.type} - ${l.touches} касаний`).join('\n')}

Последние 30 свечей 4H (time, open, high, low, close, volume):
${JSON.stringify(data.candles_4h_recent.slice(-10))}

Последние 30 свечей 1H:
${JSON.stringify(data.candles_1h_recent.slice(-10))}

Последние 30 свечей 15m:
${JSON.stringify(data.candles_15m_recent.slice(-10))}

Дай торговый сигнал по системе Герчика.`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${cfg.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: cfg.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-20250514',
      max_tokens: 1024,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: userMessage }
      ]
    }
  });

  const text = response.choices[0].message.content;

  // Parse JSON from response (handle markdown code blocks)
  let jsonStr = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) jsonStr = jsonMatch[1];

  const signal = JSON.parse(jsonStr.trim());
  signal.pair = data.symbol;
  signal._metadata = {
    lastPrice: data.lastPrice,
    volume24h: data.volume24h,
    levels_4h: data.levels_4h,
    levels_1h: data.levels_1h,
    trend_4h: data.trend_4h,
    trend_1h: data.trend_1h,
    baseUrl: data.baseUrl
  };

  return [{ json: signal }];

} catch (e) {
  // Claude API unavailable — don't trade, send alert
  return [{
    json: {
      action: 'WAIT',
      pair: data.symbol,
      confidence: 0,
      reasoning: `OpenRouter API error: ${e.message}`,
      _error: true,
      _metadata: { baseUrl: data.baseUrl }
    }
  }];
}

// =============================================
// STEP 5: Filter — only pass actionable signals
// =============================================
const cfg = $getWorkflowStaticData('global');
const signal = $input.first().json;

const MIN_CONFIDENCE = parseInt(cfg.MIN_CONFIDENCE || '75');
const MIN_RR = parseFloat(cfg.MIN_RISK_REWARD || '3');

const isActionable = (
  signal.action !== 'WAIT' &&
  signal.confidence >= MIN_CONFIDENCE &&
  signal.risk_reward_ratio >= MIN_RR &&
  signal.timeframe_alignment === true &&
  (signal.level_strength === 'strong' || signal.level_strength === 'medium')
);

// Also check for OpenRouter API errors
if (signal._error) {
  return [{ json: { ...signal, _pass: false, _alert: true } }];
}

return [{ json: { ...signal, _pass: isActionable } }];

// Log all scanned pairs summary
const cfg = $getWorkflowStaticData('global');
const items = $input.all();
const signals = items.filter(i => i.json._pass === true);
const errors = items.filter(i => i.json._alert === true);

let message = '📡 <b>Market Scanner Report</b>\n\n';
message += `<b>Пар проверено:</b> ${items.length}\n`;
message += `<b>Сигналов найдено:</b> ${signals.length}\n\n`;

for (const sig of signals) {
  const s = sig.json;
  const emoji = s.action === 'BUY' ? '🟢' : '🔴';
  message += `${emoji} <b>${s.pair}</b> — ${s.action}\n`;
  message += `   Вход: <code>${s.entry_price}</code>  SL: <code>${s.stop_loss}</code>\n`;
  message += `   TP1: <code>${s.take_profit_1}</code> R:R ${s.risk_reward_ratio}\n`;
  message += `   Уверенность: ${s.confidence}%  Уровень: ${s.level_strength}\n\n`;
}

if (errors.length > 0) {
  message += `\n⚠️ <b>Ошибки API:</b> ${errors.length}\n`;
}

message += `⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message } }];
